import os,re,sys,html
from html.parser import HTMLParser

VOID={'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}

class P(HTMLParser):
    def __init__(s):
        super().__init__(convert_charrefs=True); s.stack=[]; s.errors=[]; s.links=[]; s.ext=[]; s.ids=set(); s.title=None; s.inhead=False; s.desc=None
    def handle_starttag(s,t,a):
        d=dict(a)
        if t in VOID: return
        s.stack.append((t,s.getpos()))
        if t=='a' and 'href' in d:
            h=d['href']
            if h.startswith(('http://','https://')): s.ext.append(h)
            elif not h.startswith(('mailto:','tel:','#','data:')): s.links.append(h)
        if 'id' in d: s.ids.add(d['id'])
    def handle_endtag(s,t):
        if t in VOID: return
        if not s.stack: s.errors.append(f"stray </{t}> at {s.getpos()}"); return
        if s.stack[-1][0]!=t:
            s.errors.append(f"mismatch: </{t}> at {s.getpos()} but open <{s.stack[-1][0]}> from {s.stack[-1][1]}")
            for i in range(len(s.stack)-1,-1,-1):
                if s.stack[i][0]==t: del s.stack[i:]; return
        else: s.stack.pop()

files=[]
for r,_,fs in os.walk('.'):
    if any(x in r for x in ('/.git','/public')): continue
    for f in fs:
        if f.endswith('.html'): files.append(os.path.join(r,f))
files.sort()
bad=0
allids={}
for f in files:
    src=open(f,encoding='utf-8').read()
    p=P(); p.feed(src)
    if p.stack: bad=1; print(f"[UNCLOSED] {f}: {[t for t,_ in p.stack]}")
    for e in p.errors: bad=1; print(f"[TAG] {f}: {e}")
    allids[f]=p.ids
    # required elements
    for req,pat in [('<title>',r'<title>[^<]{5,}</title>'),
                    ('meta description',r'name="description"'),
                    ('meta viewport',r'name="viewport"'),
                    ('lang attr',r'<html[^>]*lang="en"'),
                    ('charset',r'charset="utf-8"'),
                    ('stylesheet',r'assets/css/style\.css'),
                    ('skip link',r'class="skip-link"'),
                    ('main landmark',r'<main id="main"'),
                    ('nav',r'<nav')]:
        if not re.search(pat,src,re.I): bad=1; print(f"[MISSING {req}] {f}")
    for l in p.links:
        tgt=l.split('#')[0]
        base=os.path.dirname(f)
        full=os.path.normpath(os.path.join(base,tgt))
        if not os.path.exists(full.lstrip('./')): bad=1; print(f"[BROKEN LINK] {f} -> {l}")
    print(f"OK  {f}  (links={len(p.links)} ext={len(p.ext)})")

# fragment check
for f in files:
    src=open(f,encoding='utf-8').read()
    for l in re.findall(r'href="([^"]+#([^"]+))"',src):
        path,frag=l
        if path.startswith(('http','mailto','#')): continue
        base=os.path.normpath(os.path.join(os.path.dirname(f),path))
        key='./'+base if not base.startswith('.') else base
        key=os.path.normpath(base)
        ids=allids.get(key) or allids.get('./'+key) or allids.get(key)
        if ids is None:
            cand=[k for k in allids if os.path.normpath(k.lstrip('./'))==os.path.normpath(path.lstrip('./'))]
            ids=allids[cand[0]] if cand else None
        if ids is None: bad=1; print(f"[NO TARGET] {f} -> {path}")
        elif frag not in ids: bad=1; print(f"[BROKEN FRAGMENT] {f} -> {l} (id '{frag}' not found)")
print("\nRESULT:", "FAIL" if bad else "ALL CHECKS PASSED")
sys.exit(bad)
